class DemoSeries(list):
    def fillna(self, value):
        return DemoSeries(value if x is None else x for x in self)

class DemoFrame(dict):
    def isna(self):
        return {key: [x is None for x in values] for key, values in self.items()}

df = DemoFrame(score=DemoSeries([10, None, 30]))
missing_count = sum(df.isna()["score"])
df["score"] = df["score"].fillna(0)
print(missing_count, list(df["score"]))

class DemoFrame(list):
    def dropna(self, subset):
        key = subset[0]
        return DemoFrame(row for row in self if row.get(key) is not None)

df = DemoFrame([{"score": 10}, {"score": None}, {"score": 30}])
clean = df.dropna(subset=["score"])
print(len(clean))
